import { useRef, useState } from 'react';
import { createGame } from '../game.ts';
import { parseBoardCode, isValidSize } from '../deck.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { freshBoardCode } from './fresh-board.ts';
import { activateSession, initialSession, replaceGame, SessionNotice } from './session.ts';
import { readPreferences } from './storage.ts';
import { browserStore, useSavedPreferences } from './use-saved-preferences.ts';
import { useSessionClock } from './use-session-clock.ts';
import type { Session } from './session.ts';

const MatchTone = 660;
const WinTone = 880;

function chime(frequency: number): void {
  const Context = window.AudioContext as typeof AudioContext | undefined;
  if (!Context) return;
  const audio = new Context();
  const tone = audio.createOscillator();
  const level = audio.createGain();
  tone.frequency.value = frequency;
  level.gain.value = 0.05;
  tone.connect(level).connect(audio.destination);
  tone.onended = () => void audio.close();
  tone.start();
  tone.stop(audio.currentTime + 0.12);
}

export function useGame() {
  const [store] = useState(browserStore);
  const [session, setSession] = useState(() => {
    const preferences = readPreferences(store);
    return initialSession(freshBoardCode(preferences.size), preferences);
  });
  const current = useRef(session);

  function commit(next: Session): void {
    if (next === current.current) return;
    current.current = next;
    setSession(next);
  }

  const clock = useSessionClock(session, current, commit);
  useSavedPreferences(store, session.preferences);

  function newGame(size = current.current.game.size): void {
    if (!isValidSize(size)) return;
    const next = createGame(freshBoardCode(size, current.current.game.seed));
    clock.reset();
    commit(replaceGame(current.current, next, false));
  }

  function restart(): void {
    clock.reset();
    commit(replaceGame(current.current, createGame(current.current.game.boardCode), false));
  }

  function notice(feedback: string): void {
    commit({
      ...current.current,
      feedback,
      loadNotice: feedback,
      announcement: current.current.announcement + 1,
    });
  }

  function loadBoard(code: string): boolean {
    code = code.trim();
    if (!parseBoardCode(code)) {
      notice(SessionNotice.invalidBoard);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, createGame(code), false));
    return true;
  }

  function loadSnapshot(text: string): boolean {
    const game = decodeSnapshot(text);
    if (!game) {
      notice(SessionNotice.invalidSnapshot);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, game, true));
    return true;
  }

  function exportSnapshot(): string {
    // Rendered state can trail the active clock by a tick.
    clock.synchronize();
    return encodeSnapshot(current.current.game);
  }

  function activate(index: number): void {
    clock.synchronize();
    const matched = current.current.game.matched.length;
    commit(activateSession(current.current, index));
    if (current.current.game.matched.length > matched) chime(current.current.celebration ? WinTone : MatchTone);
  }

  function resume(): void {
    clock.reset();
    commit({
      ...current.current,
      paused: false,
      feedback: '',
      loadNotice: '',
    });
  }

  return { session, newGame, restart, loadBoard, loadSnapshot, exportSnapshot, activate, resume };
}
import { activateCard, advanceGame, createGame, isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { rememberBest } from './storage.ts';
import type { GameState } from '../game.ts';
import type { Preferences } from './storage.ts';

export interface Session {
  readonly game: GameState;
  readonly paused: boolean;
  readonly generation: number;
  readonly feedback: string;
  readonly loadNotice: string;
  readonly announcement: number;
  readonly celebration: boolean;
  readonly preferences: Preferences;
}

export const SessionNotice = {
  loaded: 'Loaded snapshot. Select Resume to continue.',
  loadedCompleted: 'Loaded completed snapshot.',
  invalidBoard: 'Invalid board code.',
  invalidSnapshot: 'Invalid snapshot.',
} as const;

export function initialSession(code: string, preferences: Preferences): Session {
  return {
    game: createGame(code),
    paused: false,
    generation: 0,
    feedback: '',
    loadNotice: '',
    announcement: 0,
    celebration: false,
    preferences,
  };
}

export function replaceGame(session: Session, game: GameState, imported: boolean): Session {
  const paused = imported && !isWon(game);
  const loadNotice = imported
    ? paused
      ? SessionNotice.loaded
      : SessionNotice.loadedCompleted
    : '';
  return {
    ...session,
    game,
    paused,
    generation: session.generation + 1,
    celebration: false,
    preferences: { ...session.preferences, size: game.size },
    // Only loads have a published status. A new deal clears the last turn result silently.
    announcement: imported ? session.announcement + 1 : session.announcement,
    feedback: loadNotice,
    loadNotice,
  };
}

export function tickSession(session: Session, generation: number, milliseconds: number): Session {
  if (session.generation !== generation || session.paused) return session;
  const game = advanceGame(session.game, milliseconds);
  return game === session.game ? session : { ...session, game };
}

export function activateSession(session: Session, index: number): Session {
  if (session.paused) return session;
  const game = activateCard(session.game, index);
  if (game === session.game) return session;
  if (game.selection.kind === SelectionKind.one) return { ...session, game };
  const won = isWon(game);
  const feedback = won
    ? `Pair found. All pairs found in ${game.moves} moves and ${formatElapsed(game.elapsedMs)}.`
    : game.selection.kind === SelectionKind.mismatch
      ? 'No match. Cards close after a short pause.'
      : `Pair found. ${game.matched.length / 2} ${game.matched.length === 2 ? 'pair' : 'pairs'} matched.`;
  const preferences = won
    ? rememberBest(session.preferences, game.size, game.moves)
    : session.preferences;
  return {
    ...session,
    game,
    feedback,
    announcement: session.announcement + 1,
    preferences,
    celebration: won,
  };
}
{
  "initial": "",
  "mismatch": "No match. Cards close after a short pause.",
  "matched": "Pair found. 1 pair matched.",
  "won": "Pair found. All pairs found in 8 moves and 0:00."
}
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { test } from 'vitest';
import { activateCard, createGame, isWon, MISMATCH_MS, MOVES_MAX } from '../game.ts';
import { boardCode } from '../deck.ts';
import {
  activateSession,
  initialSession,
  replaceGame,
  tickSession,
  SessionNotice,
} from './session.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS } from '../game.fixture.ts';

const EMPTY_PREFERENCES = { size: 4, bestMoves: {} };

test('session generation rejects earlier callbacks after replacing a game', () => {
  const first = activateSession(
    activateSession(initialSession(EXAMPLE_CODE, EMPTY_PREFERENCES), 0),
    1,
  );
  const restarted = replaceGame(first, createGame(EXAMPLE_CODE), false);
  assert.equal(tickSession(restarted, first.generation, MISMATCH_MS), restarted);
  assert.equal(restarted.game.moves, 0);
  assert.equal(restarted.game.started, false);
  const active = activateSession(restarted, 2);
  assert.equal(tickSession(active, first.generation, MISMATCH_MS), active);
  const changed = replaceGame(first, createGame(boardCode(6, 1)), false);
  assert.equal(changed.preferences.size, 6);
});

test('an imported session blocks input and active time until Resume', () => {
  const first = activateSession(
    activateSession(initialSession(EXAMPLE_CODE, EMPTY_PREFERENCES), 0),
    1,
  );
  const paused = replaceGame(first, first.game, true);
  assert.equal(paused.feedback, SessionNotice.loaded);
  assert.equal(paused.loadNotice, paused.feedback);
  assert.equal(paused.announcement, first.announcement + 1);
  assert.equal(activateSession(paused, 2), paused);
  assert.equal(tickSession(paused, paused.generation, MISMATCH_MS), paused);
  assert.equal(paused.celebration, false);
  const pausedOne = replaceGame(paused, activateCard(createGame(EXAMPLE_CODE), 0), true);
  assert.equal(activateSession(pausedOne, 2), pausedOne, 'C10 paused import blocks activation');
  const resumed = { ...paused, paused: false };
  assert.notEqual(
    tickSession(resumed, resumed.generation, MISMATCH_MS).game.selection.kind,
    first.game.selection.kind,
  );
});

test('turn announcements happen once and repeat identical results as separate events', () => {
  const initial = initialSession(EXAMPLE_CODE, EMPTY_PREFERENCES);
  const first = activateSession(initial, 0);
  assert.equal(first.announcement, initial.announcement);
  const mismatch = activateSession(first, 1);
  assert.equal(mismatch.announcement, initial.announcement + 1);
  const closed = tickSession(mismatch, mismatch.generation, MISMATCH_MS);
  assert.equal(closed.announcement, mismatch.announcement);
  assert.equal(closed.feedback, mismatch.feedback);
  const repeated = activateSession(activateSession(closed, 0), 1);
  assert.equal(repeated.feedback, mismatch.feedback);
  assert.equal(repeated.announcement, mismatch.announcement + 1);
});

test('a new completion records bests but completed imports never do', () => {
  let session = initialSession(EXAMPLE_CODE, EMPTY_PREFERENCES);
  for (const pair of EXAMPLE_PAIRS)
    for (const index of pair) session = activateSession(session, index);
  assert.equal(isWon(session.game), true);
  assert.equal(session.preferences.bestMoves['4'], EXAMPLE_PAIRS.length);
  assert.equal(session.celebration, true);
  assert.equal(session.announcement, EXAMPLE_PAIRS.length);
  const imported = replaceGame(initialSession(EXAMPLE_CODE, EMPTY_PREFERENCES), session.game, true);
  assert.equal(imported.paused, false);
  assert.equal(imported.feedback, SessionNotice.loadedCompleted);
  assert.equal(imported.loadNotice, SessionNotice.loadedCompleted);
  assert.equal(imported.announcement, 1);
  assert.equal(imported.celebration, false);
  assert.equal(tickSession(imported, imported.generation, MISMATCH_MS), imported);
  assert.deepEqual(imported.preferences.bestMoves, {});
  assert.deepEqual(activateSession({ ...imported, paused: false }, 0).preferences.bestMoves, {});
  const pending = {
    ...session.game,
    matched: EXAMPLE_PAIRS.slice(0, -1).flat(),
    moves: EXAMPLE_PAIRS.length - 1,
  };
  let restored = { ...replaceGame(imported, pending, true), paused: false };
  for (const index of EXAMPLE_PAIRS[EXAMPLE_PAIRS.length - 1] ?? [])
    restored = activateSession(restored, index);
  assert.equal(restored.preferences.bestMoves['4'], EXAMPLE_PAIRS.length);
});

test('an imported game at the move cap records the capped count as its best', () => {
  const game = { ...createGame(EXAMPLE_CODE), started: true, moves: MOVES_MAX };
  const imported = replaceGame(initialSession(EXAMPLE_CODE, EMPTY_PREFERENCES), game, true);
  let session = { ...imported, paused: false };
  for (const pair of EXAMPLE_PAIRS)
    for (const index of pair) session = activateSession(session, index);
  assert.equal(session.preferences.bestMoves['4'], MOVES_MAX);
});

test('turn feedback matches the reviewed message snapshot', async () => {
  const initial = initialSession(EXAMPLE_CODE, EMPTY_PREFERENCES);
  const mismatch = activateSession(activateSession(initial, 0), 1);
  const matched = activateSession(activateSession(initial, 2), 6);
  let won = initial;
  for (const pair of EXAMPLE_PAIRS) for (const index of pair) won = activateSession(won, index);
  const expected: unknown = JSON.parse(
    await readFile(new URL('./session.feedback.fixture.json', import.meta.url), 'utf8'),
  );
  assert.deepEqual(
    {
      initial: initial.feedback,
      mismatch: mismatch.feedback,
      matched: matched.feedback,
      won: won.feedback,
    },
    expected,
  );
});
import { useRef } from 'react';
import { Board } from './board/Board.tsx';
import { Controls } from './controls/Controls.tsx';
import { Reproduction } from './controls/Reproduction.tsx';
import { GameStatus } from './status/GameStatus.tsx';
import type { BoardFocus } from './board/Board.tsx';
import { useGame } from './session/use-game.ts';
import './game.css';

export function Game() {
  const controller = useGame();
  const { session } = controller;
  const { game } = session;
  const board = useRef<BoardFocus>(null);
  function resume(): void {
    board.current?.focusRemembered();
    controller.resume();
  }
  return (
    <main>
      <header>
        <p className="eyebrow">A little focus. A perfect pair.</p>
        <h1>Neon Pairs</h1>
